#!/usr/bin/env node
// Compiles all chapter folders under chapters/* into src/chapters/generated/catalog-data.ts,
// and optionally (--verify) runs a headless playthrough across every playable chapter level
// with real enemy tick pressure (--ticks 2) asserting 0 deaths and clean completion.
//
// Usage:
//   node scripts/harness/generate-chapter.mjs
//   node scripts/harness/generate-chapter.mjs --verify --ticks 2
//   node scripts/harness/generate-chapter.mjs --check   (asserts generated file is up-to-date)
import { existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { parseArgs, projectRoot, withProcgen } from './lib/load.mjs';

const args = parseArgs(process.argv.slice(2), ['--ticks', '--chapter']);
const ticksPerCmd = Number(args.val('--ticks', 2));
const filterChapter = args.val('--chapter', '');
const chaptersDir = resolve(projectRoot, 'chapters');
const outFile = resolve(projectRoot, 'src/chapters/generated/catalog-data.ts');

const chapterSlugs = readdirSync(chaptersDir)
  .filter((d) => statSync(resolve(chaptersDir, d)).isDirectory())
  .sort();

const manifests = [];
const levelsByChapter = {};
const comixByChapter = {};
const dialogsByChapter = {};

for (const slug of chapterSlugs) {
  const cDir = resolve(chaptersDir, slug);
  const mPath = resolve(cDir, 'chapter.manifest.json');
  if (!existsSync(mPath)) continue;

  const manifest = JSON.parse(readFileSync(mPath, 'utf8'));
  manifests.push(manifest);

  if (manifest.comix) {
    const comixPath = resolve(cDir, manifest.comix.specPath);
    const dialogsPath = resolve(cDir, manifest.comix.dialogsPath);
    if (existsSync(comixPath)) {
      comixByChapter[slug] = JSON.parse(readFileSync(comixPath, 'utf8'));
    }
    if (existsSync(dialogsPath)) {
      dialogsByChapter[slug] = JSON.parse(readFileSync(dialogsPath, 'utf8'));
    }
  }

  const levelSpecs = [];
  for (const lvl of manifest.levels ?? []) {
    if (!lvl.specPath) continue;
    const lPath = resolve(cDir, lvl.specPath);
    if (existsSync(lPath)) {
      levelSpecs.push(JSON.parse(readFileSync(lPath, 'utf8')));
    }
  }
  if (levelSpecs.length > 0) {
    levelSpecs.sort((a, b) => a.index - b.index);
    levelsByChapter[slug] = levelSpecs;
  }
}

manifests.sort((a, b) => a.issueNumber - b.issueNumber);

const generatedTs = `// AUTO-GENERATED by scripts/harness/generate-chapter.mjs — DO NOT EDIT BY HAND.
import type { ChapterDialogs, ChapterManifest, ComixStorySpec, LevelSpec } from '../types.js';

export const GENERATED_MANIFESTS: ChapterManifest[] = ${JSON.stringify(manifests, null, 2)};

export const GENERATED_LEVELS_BY_CHAPTER: Record<string, LevelSpec[]> = ${JSON.stringify(levelsByChapter, null, 2)};

export const GENERATED_COMIX_BY_CHAPTER: Record<string, ComixStorySpec> = ${JSON.stringify(comixByChapter, null, 2)};

export const GENERATED_DIALOGS_BY_CHAPTER: Record<string, ChapterDialogs> = ${JSON.stringify(dialogsByChapter, null, 2)};
`;

if (args.flag('--check')) {
  const existing = existsSync(outFile) ? readFileSync(outFile, 'utf8') : '';
  if (existing !== generatedTs) {
    console.error('catalog-data.ts is out of sync with chapters/*. Run: node scripts/harness/generate-chapter.mjs');
    process.exit(1);
  }
  console.log('catalog-data.ts is in sync with chapters/*');
} else {
  mkdirSync(resolve(projectRoot, 'src/chapters/generated'), { recursive: true });
  writeFileSync(outFile, generatedTs);
  console.log(
    `generated ${outFile} (${manifests.length} manifests, ${Object.keys(levelsByChapter).length} playable level packs)`,
  );
}

if (args.flag('--verify')) {
  await withProcgen(async (_p, vite) => {
    const { createChapterSession } = await vite.ssrLoadModule('/src/chapters/chapter-session.ts');

    for (const [slug, specs] of Object.entries(levelsByChapter)) {
      if (filterChapter && slug !== filterChapter) continue;

      const session = createChapterSession({ chapterId: slug });
      session.skipIntro();
      let deaths = 0;
      let totalCmds = 0;

      for (const lvl of specs) {
        const curLevel = session.getCurrentLevel();
        if (curLevel.id !== lvl.id) {
          throw new Error(`[${slug}] Expected session to be on "${lvl.id}", but got "${curLevel.id}"`);
        }

        for (const cmd of lvl.solutionCommands) {
          for (let t = 0; t < ticksPerCmd; t++) {
            const tr = session.tick();
            for (const ev of tr.events) {
              if (ev.type === 'PLAYER_RESPAWNED') deaths++;
            }
          }
          const res = session.exec(cmd);
          totalCmds++;
          for (const ev of res.events) {
            if (ev.type === 'PLAYER_RESPAWNED') deaths++;
          }
        }
      }

      const snap = session.snapshot();
      if (!snap.ended) {
        throw new Error(`[${slug}] Playthrough finished all solutionCommands, but snapshot.ended === false (cwd=${snap.cwd})`);
      }
      if (deaths > 0) {
        throw new Error(`[${slug}] Playthrough suffered ${deaths} death(s) under --ticks ${ticksPerCmd}`);
      }

      console.log(
        `verified [${slug}]: ${specs.length} levels cleared, ended=${snap.ended}, hp=${snap.hp}/${snap.maxHp}, ram=${snap.ram}GB, ssd=${snap.ssd}GB, cmds=${totalCmds}, deaths=${deaths}, rank=${snap.rank}`,
      );
    }
  });
}
